def generate(rng):
    h=rng.randint(6,18); w=rng.randint(6,18)
    g=[[0]*w for _ in range(h)]
    # target adjacent 5-6 pair, with 6 safely away from borders
    r=rng.randint(1,h-2); c=rng.randint(1,w-2)
    orient=rng.choice([(0,1),(0,-1),(1,0),(-1,0)])
    dr,dc=orient
    r5,c5=r,c; r6,c6=r+dr,c+dc
    g[r5][c5]=5; g[r6][c6]=6
    # distractor colored singleton cells and occasional extra 5/6, avoiding target vicinity
    palette=[4,7,8,9]
